from common import *

C = "stimulants"
STIM_BOXED = lambda n: {"boxed": {"title": "FDA boxed warning", "items": [
    f"{n} has a high potential for abuse and misuse, which can lead to a substance use disorder, including addiction. Misuse and abuse of CNS stimulants can result in overdose and death, and this risk is increased with higher doses or unapproved methods of administration, such as snorting or injection.[[fdastim]]",
    "Prescribers should assess each patient's risk before prescribing, monitor for signs of misuse throughout treatment, and counsel patients not to share their medicine.[[fdastim]]"]}}

def stim_ix(extra=()):
    return [["MAOIs (phenelzine, selegiline, linezolid)", "Dangerous rise in blood pressure", "Contraindicated within 14 days"],
            ["Other stimulants, decongestants (pseudoephedrine)", "High blood pressure, fast heart rate", "Use caution"],
            ["SSRIs, SNRIs, tramadol, triptans", "Serotonin syndrome (rare)", "Use caution"],
            ["Alcohol", "Masks drunkenness; heart strain", "Avoid"], *extra]

def stim_withdrawal(n, extra=()):
    return {"q": f"What happens when you stop {n}?", "blocks": [
        {"p": f"Stopping {n} after regular prescribed use does not cause dangerous physical withdrawal. ADHD symptoms return, and some people feel tired or low for a few days. After heavy misuse, a \"crash\" with exhaustion, increased sleep and appetite, and depression is common.[[label]]"},
        {"timeline": [{"when": "Days 1 to 3", "title": "Crash", "text": "Fatigue, long sleep, increased appetite, low mood, irritability."},
                      {"when": "Weeks 1 to 2", "title": "Low mood and cravings", "text": "Low energy, poor concentration, and cravings after heavy use."},
                      {"when": "Weeks to months", "title": "Recovery", "text": "Mood and energy normalize; depression should be watched for."}]},
        {"p": "There is no need to taper prescribed stimulants for safety, but anyone who feels severe depression or suicidal thoughts after stopping should contact a clinician or call or text 988."},
        *extra]}

STIM_INTL = lambda uk="Class B; prescription only (Schedule 2 controlled drug)": [["United Kingdom", uk], ["Canada", "Schedule I of the Controlled Drugs and Substances Act; prescription only"],
                                                                                    ["Australia", "Schedule 8 controlled drug"], ["International", "Schedule II of the 1971 Convention on Psychotropic Substances"]]

SHORTAGE = "**Shortages:** prescription stimulants were in short supply from 2022, and some strengths remained hard to find into 2025. If a pharmacy is out, ask about another strength, form, or nearby pharmacy, or ask the prescriber about alternatives."

